<script>
  import { splitObject } from '@splendidlabz/utils'
  import { checkForAccessibleName } from '@splendidlabz/utils/dom'
  import { mergeOpts } from '../../../utils/merge-opts.js'
  import { getTrigger, passEventToTrigger } from '../shared.js'
  import { FLOATING_OPTS_KEYS, initFloating } from './floating.js'

  let {
    class: klass = '',
    as = 'dialog',
    ref = $bindable(null),
    referenceNode = $bindable(null),
    ...props
  } = $props()

  const p = $derived(mergeOpts(props))

  const componentName = $derived(p.componentName ?? 'Popover')
  const ariaLabel = $derived(p['aria-label'])
  const ariaLabelledBy = $derived(p['aria-labelledBy'])
  const ariaDescribedBy = $derived(p['aria-describedby'])

  const id = $derived(p.id)
  const popover = $derived(p.popover ?? 'auto') // manual, hint

  const onbeforetoggle = $derived(p.onbeforetoggle ?? null)
  const ontoggle = $derived(p.ontoggle ?? null)
  const onopen = $derived(p.onopen ?? null)
  const onclose = $derived(p.onclose ?? null)

  const children = $derived(p.children)
  const rest = $derived.by(() => {
    const {
      componentName = 'Popover',
      'aria-label': ariaLabel,
      'aria-labelledBy': ariaLabelledBy,
      'aria-describedby': ariaDescribedBy,
      id,
      popover = 'auto',
      onbeforetoggle = null,
      ontoggle = null,
      onopen = null,
      onclose = null,
      children,
      ...rest
    } = p
    return rest
  })

  // ========================
  // Checks
  // ========================
  $effect(() => {
    if (!id) throw new Error(`${componentName} requires an id`)

    // Accessible name warning
    checkForAccessibleName({
      name: `${componentName} (id: ${id})`,
      ariaLabel,
      ariaLabelledBy,
    })
  })

  // ========================================
  // Logic
  // ========================================
  let trigger = null
  let floating = null

  const floatingSplit = $derived(splitObject(rest, FLOATING_OPTS_KEYS))
  const floatingOpts = $derived(floatingSplit.picked)

  // ========================================
  // Event Listeners
  // ========================================
  function beforetoggle(event) {
    if (!trigger) trigger = getTrigger(`[popovertarget="${id}"]`)
    passEventToTrigger(event, trigger)

    const { newState } = event

    if (newState === 'open') {
      // Initialize floating.
      if (!floating) {
        floating = initFloating({
          referenceNode: referenceNode || trigger,
          floatingNode: ref,
          ...floatingOpts,
        })
      }
      floating.update()
    }

    // Calculate position before showing
    if (onbeforetoggle) onbeforetoggle(event)
  }

  function handleToggle(event) {
    passEventToTrigger(event, trigger)
    const { newState } = event

    // Send open event
    if (newState === 'open') {
      if (onopen) onopen(event)
    }

    if (newState === 'closed') {
      floating.cleanup()
      // Send close event
      if (onclose) onclose(event)
    }

    // Send toggle event
    if (ontoggle) ontoggle(event)
  }
</script>

<!-- Snippets -->
<svelte:element
  this={as}
  bind:this={ref}
  {...rest}
  {id}
  class={klass}
  aria-describedby={ariaDescribedBy}
  aria-label={ariaLabel}
  aria-labelledby={ariaLabelledBy}
  onbeforetoggle={beforetoggle}
  ontoggle={handleToggle}
  {popover}
>
  {#if children}{@render children()}{/if}
</svelte:element>
